export default function createGarden(api){
  const {width:W,height:H}=api;
  const kinds=[{name:'Poppy',cost:2,value:5,color:'#e88675',time:10},{name:'Sunflower',cost:4,value:9,color:'#e5c974',time:16},{name:'Lavender',cost:3,value:7,color:'#aea0d2',time:13}];
  let beds,tool,seeds,harvests,elapsed,tip,tipTimer,done,particles,season,seasonWait,totalBlooms;
  const seasons=[{name:'Spring',goals:[3,2,2],water:7},{name:'Early summer',goals:[4,3,2],water:6.5},{name:'High summer',goals:[4,3,4],water:6},{name:'Autumn harvest',goals:[5,4,4],water:7.5}];
  const grid={x:64,y:137,size:139,gap:12,cols:4,rows:3};
  const buttons=[{x:726,y:148,w:190,h:48,label:'Plant poppy',tool:0},{x:726,y:206,w:190,h:48,label:'Plant sunflower',tool:1},{x:726,y:264,w:190,h:48,label:'Plant lavender',tool:2},{x:726,y:330,w:190,h:48,label:'Water',tool:'water'},{x:726,y:388,w:190,h:48,label:'Harvest',tool:'harvest'}];
  function note(text){tip=text;tipTimer=3;api.setHint(text);}
  function hud(){api.hud({Seeds:seeds,Blooms:harvests.reduce((a,b)=>a+b,0),Season:`${season+1}/4`, 'Poppy goal':`${harvests[0]}/${seasons[season].goals[0]}`,'Sunflower goal':`${harvests[1]}/${seasons[season].goals[1]}`,'Lavender goal':`${harvests[2]}/${seasons[season].goals[2]}`});}
  function reset(){beds=Array.from({length:12},()=>null);tool=0;seeds=16;harvests=[0,0,0];season=0;seasonWait=0;totalBlooms=0;elapsed=0;done=false;particles=[];tip='Plant a flower, then choose Water and tap the same bed.';tipTimer=5;api.setHint('Grow through four seasons. Match each season’s harvest goals. Press Water all to irrigate planted beds for 2 seeds.');hud();}
  function bedAt(x,y){for(let i=0;i<12;i++){const bx=grid.x+(i%4)*(grid.size+grid.gap),by=grid.y+Math.floor(i/4)*116;if(x>=bx&&x<=bx+grid.size&&y>=by&&y<=by+101)return i;}return -1;}
  function use(i){if(done||seasonWait>0||i<0)return;const plant=beds[i];
    if(typeof tool==='number'){if(plant){note('This bed is planted. Choose Water or Harvest.');return;}const kind=kinds[tool];if(seeds<kind.cost){note('Harvest a grown flower to earn seeds.');return;}seeds-=kind.cost;beds[i]={kind:tool,growth:0,water:0,phase:Math.random()*6};api.sound('tap');note(`Planted ${kind.name.toLowerCase()}. Add water to start it growing.`);}
    if(tool==='water'){if(!plant){note('Plant a flower in this bed first.');return;}if(plant.growth>=1){note('This bloom is ready to harvest.');return;}plant.water=1;api.sound('tap');note('Watered. Each full watering lasts about seven seconds.');}
    if(tool==='harvest'){if(!plant){note('Choose a flower to plant in this empty bed.');return;}if(plant.growth<1){note('This plant needs more time and water.');return;}const kind=kinds[plant.kind];harvests[plant.kind]++;totalBlooms++;seeds+=kind.value;const x=grid.x+(i%4)*(grid.size+grid.gap)+70,y=grid.y+Math.floor(i/4)*116+45;for(let j=0;j<10;j++)particles.push({x,y,vx:(Math.random()-.5)*90,vy:-50-Math.random()*70,life:1.2,color:kind.color});beds[i]=null;api.sound('win');note(`Harvested ${kind.name.toLowerCase()}. +${kind.value} seeds.`);if(harvests.every((n,i)=>n>=seasons[season].goals[i])){if(season<3){seasonWait=3;note(`${seasons[season].name} complete. +12 seeds for the next season.`);api.sound('win');}else{done=true;api.end(4000+Math.max(0,Math.round(1800-elapsed*3)), 'A year in bloom',`Four seasons completed · ${totalBlooms} blooms harvested · ${Math.ceil(elapsed)} seconds.`);}}}
    hud();
  }
  function pointerDown(x,y){for(const b of buttons)if(x>=b.x&&x<=b.x+b.w&&y>=b.y&&y<=b.y+b.h){tool=b.tool;note(typeof tool==='number'?`Tap an empty bed. ${kinds[tool].name} costs ${kinds[tool].cost} seeds.`:tool==='water'?'Tap a growing plant to refill its water.':'Tap a fully grown bloom to harvest.');api.sound('tap');return;}use(bedAt(x,y));}
  function keyDown(key){if(['1','2','3'].includes(key))tool=Number(key)-1;if(key.toLowerCase()==='w')tool='water';if(key.toLowerCase()==='h')tool='harvest';if(key==='4'){if(seeds<2){note('Water all costs 2 seeds. Individual watering is free.');return;}if(!beds.some(p=>p&&p.growth<1)){note('There are no growing plants to water.');return;}seeds-=2;for(const p of beds)if(p&&p.growth<1)p.water=1;note('All growing beds watered. −2 seeds.');api.sound('tap');hud();}}
  function update(dt){if(done)return;elapsed+=dt;if(seasonWait>0){seasonWait-=dt;if(seasonWait<=0){season++;harvests=[0,0,0];seeds+=12;note(`${seasons[season].name}: new harvest goals. Your planted beds carry over.`);hud();}}tipTimer=Math.max(0,tipTimer-dt);for(const p of beds){if(!p||p.growth>=1)continue;if(p.water>0){p.growth=Math.min(1,p.growth+dt/kinds[p.kind].time);p.water=Math.max(0,p.water-dt/seasons[season].water);}}for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=80*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);}
  function rr(c,x,y,w,h,r,fill){c.fillStyle=fill;c.beginPath();c.roundRect(x,y,w,h,r);c.fill();}
  function text(c,t,x,y,size,color,align='left'){c.fillStyle=color;c.font=`${size}px Arial`;c.textAlign=align;c.fillText(t,x,y);}
  function bloom(c,x,y,kind,size,phase){c.save();c.translate(x,y);if(kind===2){for(let a=0;a<6;a++){c.fillStyle=a%2?'#9e8cc4':'#beb0d9';c.beginPath();c.ellipse(Math.sin(a*2)*size*.3,-a*size*.32,size*.34,size*.23,0,0,Math.PI*2);c.fill();}}else{const petals=kind===1?11:6;for(let a=0;a<petals;a++){const angle=a*Math.PI*2/petals+phase;c.fillStyle=kinds[kind].color;c.beginPath();c.ellipse(Math.cos(angle)*size*.7,Math.sin(angle)*size*.7,size*.53,size*.4,angle,0,Math.PI*2);c.fill();}c.fillStyle=kind===1?'#75623c':'#4d4741';c.beginPath();c.arc(0,0,size*.34,0,Math.PI*2);c.fill();}c.restore();}
  function draw(c){const bg=c.createLinearGradient(0,0,0,H);bg.addColorStop(0,['#d1d9bc','#e2dfbd','#d4ddbb','#dccdb5'][season]);bg.addColorStop(1,['#b0c099','#c2c796','#b8c28e','#bda47e'][season]);c.fillStyle=bg;c.fillRect(0,0,W,H);c.fillStyle='#8aa073';c.fillRect(0,H-26,W,26);c.fillStyle='#edf0d7';c.beginPath();c.arc(866,54,46,0,7);c.fill();text(c,'Pocket Garden',64,58,34,'#344b30');text(c,`${seasons[season].name} · Season ${season+1} of 4 · ${totalBlooms} blooms harvested`,64,88,17,'#607451');
    for(let i=0;i<12;i++){const x=grid.x+i%4*(grid.size+grid.gap),y=grid.y+Math.floor(i/4)*116,p=beds[i];rr(c,x+4,y+5,grid.size,100,10,'#869970');rr(c,x,y,grid.size,98,9,'#75865d');rr(c,x+7,y+7,grid.size-14,81,6,'#665942');for(let j=0;j<18;j++){c.fillStyle='#827050';c.fillRect(x+13+(j*37)%108,y+15+(j*23)%64,3,2);}if(!p){text(c,'+',x+grid.size/2,y+57,26,'#998a66','center');continue;}
      const k=kinds[p.kind],height=15+p.growth*39,stemX=x+68,base=y+71,sway=Math.sin(elapsed*1.8+p.phase)*p.growth*2;c.strokeStyle='#9dae78';c.lineWidth=4;c.beginPath();c.moveTo(stemX,base);c.quadraticCurveTo(stemX+sway-6,base-height*.5,stemX+sway,base-height);c.stroke();c.fillStyle='#91a765';c.beginPath();c.ellipse(stemX-10,base-height*.4,13,5,-.45,0,7);c.fill();c.beginPath();c.ellipse(stemX+10,base-height*.6,13,5,.45,0,7);c.fill();if(p.growth>.35)bloom(c,stemX+sway,base-height,p.kind,(p.growth-.25)*22,p.phase);rr(c,x+13,y+80,grid.size-26,4,2,'#403e30');rr(c,x+13,y+80,(grid.size-26)*p.growth,4,2,p.growth>=1?'#ead28d':'#aeca87');if(p.growth>=1){text(c,'READY',x+grid.size/2,y+24,10,'#f2e7b5','center');}else{c.fillStyle=p.water>0?'#a2ced3':'#e7b98a';c.beginPath();c.moveTo(x+117,y+14);c.quadraticCurveTo(x+102,y+33,x+117,y+34);c.quadraticCurveTo(x+132,y+33,x+117,y+14);c.fill();}}
    text(c,'Tools & seeds',726,125,20,'#405333');for(const b of buttons){rr(c,b.x,b.y,b.w,b.h,7,b.tool===tool?'#405834':'#e3e9d1');text(c,b.label,b.x+16,b.y+29,17,b.tool===tool?'#f0f4df':'#41583a');if(typeof b.tool==='number')text(c,String(kinds[b.tool].cost),b.x+b.w-17,b.y+29,16,b.tool===tool?'#d6e7bc':'#83936f','right');}
    rr(c,726,457,190,66,7,'#becda5');text(c,`Seeds: ${seeds}`,742,485,21,'#3a5030');text(c,'Harvest to earn more.',742,508,12,'#60744e');for(let i=0;i<3;i++){const xx=64+i*200;rr(c,xx,511,185,37,5,'#dfe7ca');text(c,`${kinds[i].name}: ${harvests[i]}/${seasons[season].goals[i]}`,xx+12,536,15,'#52643d');}
    text(c,tipTimer>0?tip:'Keep plants watered. Mature blooms glow above their beds.',64,579,15,'#455b35');for(const p of particles){c.globalAlpha=p.life/1.2;c.fillStyle=p.color;c.beginPath();c.arc(p.x,p.y,5,0,7);c.fill();}c.globalAlpha=1;if(seasonWait>0){rr(c,235,225,490,130,12,'#344b30ee');text(c,`${seasons[season].name} complete`,480,274,27,'#edf0d5','center');text(c,'Your garden continues into the next season…',480,312,16,'#bdcba5','center');}}
  return{reset,update,draw,pointerDown,keyDown};
}


